/*
 * External links in the post/page body.
 *
 * Ghost hands the theme the rendered post HTML through {{content}}, so a
 * Handlebars template cannot classify the links before output. This module is
 * the progressive enhancement: it runs on post/page only, finds the links
 * inside .gh-content, and decorates the external ones with a small service
 * icon, a new-tab target and a screen-reader hint. Internal links, anchors and
 * non-HTTP schemes are left untouched.
 *
 * The icons themselves live in partials/external-link-icons.hbs as a
 * <template>; this module clones them, so the SVGs have one source of truth
 * and there is no runtime dependency or network request.
 */

// Domain -> service. The longest matching domain wins, so the table can list
// both a broad domain (amazon.com) and a narrower one (amazonaws.com) and
// subdomains (open.spotify.com) resolve to the same service as their parent.
const SERVICE_DOMAINS = [
  // Social networks already used by the footer.
  ['github.com', 'github'],
  ['github.blog', 'github'],
  ['github.io', 'github'],
  ['linkedin.com', 'linkedin'],
  ['instagram.com', 'instagram'],
  ['facebook.com', 'facebook'],
  ['fb.com', 'facebook'],
  ['x.com', 'x'],
  ['twitter.com', 'x'],
  ['youtube.com', 'youtube'],
  ['youtu.be', 'youtube'],
  ['threads.com', 'threads'],
  ['threads.net', 'threads'],
  ['bsky.app', 'bluesky'],
  ['tiktok.com', 'tiktok'],
  ['huggingface.co', 'huggingface'],

  // AI and technology.
  ['google.com', 'google'],
  ['google.dev', 'google'],
  ['anthropic.com', 'anthropic'],
  ['claude.ai', 'anthropic'],
  ['claude.com', 'anthropic'],
  ['openai.com', 'openai'],
  ['chatgpt.com', 'openai'],
  ['chat.com', 'openai'],
  ['microsoft.com', 'microsoft'],
  ['microsoft365.com', 'microsoft'],
  ['azure.com', 'microsoft'],
  ['bing.com', 'microsoft'],
  ['apple.com', 'apple'],
  ['amazon.com', 'amazon'],
  ['amazonaws.com', 'amazon'],
  ['kaggle.com', 'kaggle'],
  ['gitlab.com', 'gitlab'],
  ['npmjs.com', 'npm'],

  // Publishing and community.
  ['medium.com', 'medium'],
  ['substack.com', 'substack'],
  ['reddit.com', 'reddit'],
  ['discord.com', 'discord'],
  ['discord.gg', 'discord'],
  ['telegram.org', 'telegram'],
  ['t.me', 'telegram'],
  ['whatsapp.com', 'whatsapp'],
  ['wa.me', 'whatsapp'],
  ['spotify.com', 'spotify'],
  ['figma.com', 'figma'],
  ['notion.so', 'notion'],
  ['notion.com', 'notion'],
  ['wikipedia.org', 'wikipedia'],
  ['arxiv.org', 'arxiv'],
];

const CONTENT_SELECTOR = '.gh-content';
const LINK_SELECTOR = `${CONTENT_SELECTOR} a[href]`;

// Cards, embeds, images and figures have their own visual language. A link
// inside them keeps its card behaviour and gets no icon.
const SKIP_ANCESTORS = '.kg-card, .kg-embed-card, figure, [data-ghost-embed]';

// Lowercase the host and drop a leading "www.", so example.com and
// www.example.com compare equal in both directions.
export function normalizeHost(hostname) {
  return String(hostname || '')
    .toLowerCase()
    .replace(/^www\./, '');
}

// Exact host or a subdomain of a mapped domain; null means "generic icon".
export function serviceForHost(hostname) {
  const host = normalizeHost(hostname);
  let service = null;
  let length = -1;

  for (const [domain, candidate] of SERVICE_DOMAINS) {
    if ((host === domain || host.endsWith(`.${domain}`)) && domain.length > length) {
      service = candidate;
      length = domain.length;
    }
  }

  return service;
}

// A link is external when it resolves to HTTP(S) on a host other than the
// page's own host. Returns null for internal links, anchors, mailto:, tel:,
// javascript: and anything that is not a valid URL.
export function classifyLink(rawHref, pageUrl) {
  if (!rawHref) return null;

  let url;
  let page;
  try {
    url = new URL(rawHref, pageUrl);
    page = new URL(pageUrl);
  } catch {
    return null;
  }

  if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;
  if (normalizeHost(url.hostname) === normalizeHost(page.hostname)) return null;

  return { href: url.href, service: serviceForHost(url.hostname) };
}

// Preserve tokens already on the link (nofollow, sponsored, ugc) and add the
// two we need, without duplicates or case differences.
export function mergeRel(existing = '') {
  const tokens = new Set(String(existing).toLowerCase().split(/\s+/).filter(Boolean));
  tokens.add('noopener');
  tokens.add('noreferrer');
  return [...tokens].join(' ');
}

// A link that wraps only an image (or nothing) is a media link, not a text
// link: no icon and no new-tab change.
export function hasUsableText(text) {
  return typeof text === 'string' && text.replace(/\s+/g, ' ').trim().length > 0;
}

function cloneIcon(template, service) {
  if (!template) return null;
  const content = template.content || template;
  return (
    content.querySelector(`[data-external-icon="${service}"]`) ||
    content.querySelector('[data-external-icon="generic"]')
  );
}

export function decorateLink(link, service, template) {
  if (!link || link.hasAttribute('data-external-link')) return false;

  const serviceName = service || 'generic';

  link.dataset.externalLink = '';
  link.dataset.externalService = serviceName;
  link.target = '_blank';
  link.rel = mergeRel(link.rel);

  const icon = cloneIcon(template, serviceName);
  if (icon) link.append(icon.cloneNode(true));

  const label = template?.content?.querySelector('[data-external-link-label]');
  if (label && !link.querySelector('[data-external-link-label]')) {
    link.append(label.cloneNode(true));
  }

  return true;
}

export function initExternalLinks(doc = document, pageUrl = doc.defaultView?.location?.href) {
  if (!pageUrl) return;
  const template = doc.getElementById('gh-external-link-icons');

  doc.querySelectorAll(LINK_SELECTOR).forEach((link) => {
    if (link.hasAttribute('data-external-link')) return;
    if (link.closest(SKIP_ANCESTORS)) return;
    if (!hasUsableText(link.textContent)) return;

    const result = classifyLink(link.getAttribute('href'), pageUrl);
    if (!result) return;

    decorateLink(link, result.service, template);
  });
}
